<?php
const DB_PATH = __DIR__ . '/storage/security.sqlite';
date_default_timezone_set('Asia/Jakarta');
if (!is_dir(__DIR__.'/storage')) mkdir(__DIR__.'/storage',0775,true);
function db(){static $p;if($p)return $p;$p=new PDO('sqlite:'.DB_PATH);$p->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$p->setAttribute(PDO::ATTR_DEFAULT_FETCH_MODE,PDO::FETCH_ASSOC);$p->exec('PRAGMA foreign_keys=ON');init($p);return $p;}
function init($p){$p->exec("CREATE TABLE IF NOT EXISTS domains(id INTEGER PRIMARY KEY,name TEXT UNIQUE,description TEXT DEFAULT '')");$p->exec("CREATE TABLE IF NOT EXISTS controls(id INTEGER PRIMARY KEY,domain_id INTEGER,name TEXT,weight REAL DEFAULT 1,active INTEGER DEFAULT 1,FOREIGN KEY(domain_id) REFERENCES domains(id) ON DELETE CASCADE)");$p->exec("CREATE TABLE IF NOT EXISTS assets(id INTEGER PRIMARY KEY,asset_code TEXT UNIQUE,name TEXT,type TEXT,location TEXT DEFAULT '',ip_address TEXT DEFAULT '',owner TEXT DEFAULT '',active INTEGER DEFAULT 1)");$p->exec("CREATE TABLE IF NOT EXISTS assessments(id INTEGER PRIMARY KEY,asset_id INTEGER,control_id INTEGER,status TEXT CHECK(status IN ('YES','NO','N/A')),evidence TEXT DEFAULT '',notes TEXT DEFAULT '',assessed_at TEXT DEFAULT CURRENT_TIMESTAMP,UNIQUE(asset_id,control_id),FOREIGN KEY(asset_id) REFERENCES assets(id) ON DELETE CASCADE,FOREIGN KEY(control_id) REFERENCES controls(id) ON DELETE CASCADE)");$p->exec("CREATE TABLE IF NOT EXISTS findings(id INTEGER PRIMARY KEY,asset_id INTEGER,control_id INTEGER,severity TEXT DEFAULT 'Medium',title TEXT,description TEXT DEFAULT '',recommendation TEXT DEFAULT '',status TEXT DEFAULT 'Open',due_date TEXT DEFAULT '',created_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(asset_id) REFERENCES assets(id) ON DELETE CASCADE,FOREIGN KEY(control_id) REFERENCES controls(id) ON DELETE CASCADE)");if(!$p->query('SELECT COUNT(*) FROM domains')->fetchColumn())seed($p);}
function seed($p){$p->beginTransaction();$s=$p->prepare('INSERT INTO domains VALUES(NULL,?,?)');foreach([['Network','Network infrastructure'],['Server','Server infrastructure'],['Endpoint','Workstation and endpoint']] as $x)$s->execute($x);$d=$p->prepare('SELECT id FROM domains WHERE name=?');$c=$p->prepare('INSERT INTO controls(domain_id,name) VALUES(?,?)');$map=['Network'=>['Backup','Patching','MFA','Hardening','Internet Access','Configuration Backup','Logging'],'Server'=>['Backup','Patching','MFA','Hardening','EDR / Antivirus','Vulnerability Management','Logging','Monitoring'],'Endpoint'=>['EDR / Antivirus','Patching','Firewall','Disk Encryption','USB Control','MFA','Hardening']];foreach($map as $n=>$list){$d->execute([$n]);$id=$d->fetchColumn();foreach($list as $v)$c->execute([$id,$v]);}$a=$p->prepare('INSERT INTO assets(asset_code,name,type,location,ip_address,owner) VALUES(?,?,?,?,?,?)');foreach([['NET-001','Fortigate 201G','Network','DC JTP','192.168.10.1','IT Infrastructure'],['NET-002','Core Switch','Network','DC JTP','192.168.10.2','IT Infrastructure'],['SRV-001','Application Server 01','Server','DC JTP','192.168.20.10','System Team'],['SRV-002','Monitoring Server','Server','DC JTP','192.168.20.20','System Team'],['END-001','Security Admin Workstation','Endpoint','Office','192.168.30.10','IT Security'],['END-002','Helpdesk Workstation 01','Endpoint','Office','192.168.30.11','IT Support']] as $x)$a->execute($x);$controls=$p->query('SELECT c.id,d.name domain FROM controls c JOIN domains d ON d.id=c.domain_id')->fetchAll();$assets=$p->query('SELECT * FROM assets')->fetchAll();$q=$p->prepare('INSERT INTO assessments(asset_id,control_id,status,notes) VALUES(?,?,?,?)');foreach($assets as $a1)foreach($controls as $c1)if($a1['type']==$c1['domain']){$n=crc32($a1['asset_code'].'|'.$c1['id'])%10;$q->execute([$a1['id'],$c1['id'],$n<7?'YES':($n<9?'NO':'N/A'),'Demo data']);}$p->commit();}
function jsonout($data,$code=200){http_response_code($code);header('Content-Type: application/json');echo json_encode($data);exit;}
